if (isset($_GET['source'])) {
    $index = file_get_contents(__DIR__ . '/index.php');
    if (preg_match('~<li>\\s*<div class="entry-title"><a href="ogden-frame-club\\.php">.*?</li>~s', $index, $entry)
        && preg_match('~Inspired by Jon\\x27s <a href="([^"]+)"~', $entry[0], $link)) {
        header('Location: ' . html_entity_decode($link[1], ENT_QUOTES, 'UTF-8'), true, 302); exit;
    }
    http_response_code(404); exit('Find the original post in the gallery.');
}
if (isset($_GET['art'])) {
    header('Content-Type: image/webp');
