<style>
:root{--paper:#eee9db;--ink:#203e3a;--orange:#bc442c;--muted:#57665c;--line:#c5c4b3}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.5 "Palatino Linotype","Book Antiqua",Palatino,serif;background-image:repeating-linear-gradient(90deg,transparent 0 71px,#203e3a05 72px)}a{color:inherit;text-underline-offset:4px}button,input{font:inherit}button{cursor:pointer;min-height:44px;border:1px solid var(--ink);color:var(--ink);background:transparent;padding:10px 16px;border-radius:3px}button:hover{background:#203e3a12}button:focus-visible,a:focus-visible,input:focus-visible,canvas:focus-visible{outline:3px solid var(--orange);outline-offset:4px}button:disabled{cursor:wait;opacity:.5}.mono,.eyebrow,label,nav,footer,.readout{font-family:"Courier New",monospace}header,main,footer{max-width:1240px;margin:auto;padding:24px 32px}header{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);font-size:12px;letter-spacing:1px}.identity{display:flex;align-items:center;gap:10px}.mark{font-size:25px;line-height:1;color:var(--orange)}.intro{display:grid;grid-template-columns:1.25fr 1fr;gap:60px;align-items:end;margin:28px 0 36px}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--orange)}h1{font-size:clamp(46px,6.4vw,83px);line-height:.96;font-weight:400;letter-spacing:-3px;margin:14px 0}h1 em{font-weight:400;color:var(--orange)}.intro p{max-width:420px;margin:0 0 6px;font-size:19px}nav{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:22px;font-size:12px}nav button{flex:1;text-align:left;min-width:130px}nav button[aria-pressed=true]{background:var(--ink);color:var(--paper)}nav button span{display:block;opacity:.6;font-size:10px;letter-spacing:1px}.workbench{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:28px;align-items:start}.camera{background:#25312e;padding:14px;border-radius:8px;box-shadow:0 15px 25px #203e3a20}.camera-top{display:flex;justify-content:space-between;color:#e3dec8;font:10px "Courier New",monospace;letter-spacing:1.5px;padding:2px 2px 14px}.viewfinder{position:relative;background:#99b2af;overflow:hidden;aspect-ratio:3/2}#scene{width:100%;height:100%;display:block;touch-action:none;cursor:grab}.guide{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,transparent calc(33.333% - .5px),#fff8 33.333%,transparent calc(33.333% + .5px),transparent calc(66.666% - .5px),#fff8 66.666%,transparent calc(66.666% + .5px)),linear-gradient(0deg,transparent calc(33.333% - .5px),#fff8 33.333%,transparent calc(33.333% + .5px),transparent calc(66.666% - .5px),#fff8 66.666%,transparent calc(66.666% + .5px))}.guide.off{display:none}.flash{position:absolute;inset:0;pointer-events:none;background:white;opacity:0}.flash.fire{animation:flash .3s ease-out}@keyframes flash{0%{opacity:.85}100%{opacity:0}}.camera-bottom{color:#dedcc9;display:flex;justify-content:space-between;gap:12px;padding:12px 2px 0;font:10px "Courier New",monospace}.camera-bottom button{color:inherit;border-color:#8e9b8c;font-size:11px;min-height:36px;padding:6px 10px}.note{font-size:13px;color:var(--muted);margin:13px 0}.brief{border-top:3px solid var(--orange);padding-top:15px}.brief h2{font-size:31px;line-height:1.1;font-weight:400;margin:8px 0 14px}.brief p{font-size:15px}.readout{font-size:10px;letter-spacing:1px;border-bottom:1px solid var(--line);padding-bottom:12px}label{display:flex;justify-content:space-between;font-size:11px;margin:18px 0 5px}input[type=range]{width:100%;accent-color:var(--orange);min-height:28px;margin:0;cursor:pointer}.shutter{display:block;background:var(--orange);color:#fff8e9;border-color:var(--orange);width:100%;margin:22px 0 10px;font:13px "Courier New",monospace;letter-spacing:2px}.shutter:hover{background:#9c3421}.shutter:before{content:"●";font-size:18px;margin-right:12px}.secondary{display:flex;gap:8px}.secondary button{flex:1;font:11px "Courier New",monospace;padding:9px}.feedback{min-height:100px;margin-top:20px;border-top:1px dashed var(--line);padding-top:12px;font-size:14px}.feedback strong{font-size:23px;font-weight:400;display:block}.film-heading{display:flex;justify-content:space-between;gap:12px;align-items:end;margin:45px 0 18px;border-bottom:1px solid var(--ink);padding-bottom:14px}.film-heading h2{font-size:30px;font-weight:400;margin:0}.film-heading p{margin:0;font:11px "Courier New",monospace}.film{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.print{background:#faf8f0;box-shadow:0 4px 10px #203e3a12;padding:10px 10px 16px;transform:rotate(-1deg);min-width:0}.print:nth-child(even){transform:rotate(1deg)}.print img,.blank{width:100%;aspect-ratio:3/2;object-fit:cover;display:block;background:#d7dacd}.blank{display:flex;align-items:center;justify-content:center;color:#7b8375;font:30px "Courier New",monospace}.print h3{font-size:15px;font-weight:400;margin:10px 0 2px}.print p{font:10px "Courier New",monospace;margin:0;color:var(--muted)}.print button{font:10px "Courier New",monospace;padding:5px 8px;margin-top:10px;min-height:34px}.closing{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin:48px 0 20px;padding-top:20px;border-top:1px solid var(--line)}.closing p{font-size:14px;margin:0}.closing h2{font-size:21px;margin:0 0 8px;font-weight:400}footer{font-size:10px;display:flex;justify-content:space-between;border-top:1px solid var(--line);gap:15px}.loading{position:absolute;inset:0;display:grid;place-items:center;background:#c4d0c4;font:13px "Courier New",monospace}.loading[hidden]{display:none}@media(max-width:850px){.workbench{grid-template-columns:1fr}.brief{display:grid;grid-template-columns:1fr 1fr;gap:0 28px}.brief .assignment{grid-column:1/-1}.brief h2{font-size:28px}.actions{align-self:end}.feedback{grid-column:1/-1;min-height:75px}.intro{gap:30px}.intro p{font-size:16px}}@media(max-width:540px){header,main,footer{padding:18px}.intro{grid-template-columns:1fr;gap:18px;margin:24px 0}h1{letter-spacing:-2px}.intro p{max-width:none}nav{gap:6px}nav button{min-width:43%;padding:9px 10px}.camera{padding:9px}.camera-top{font-size:8px;letter-spacing:1px}.workbench{gap:22px}.brief{gap:0 18px}.film{grid-template-columns:1fr 1fr;gap:16px 12px}.film-heading{align-items:start}.film-heading h2{font-size:25px}.film-heading p{max-width:90px;line-height:1.5}.closing{grid-template-columns:1fr;gap:20px}.camera-bottom{font-size:8px}.note{font-size:12px}footer{line-height:1.7}}@media(prefers-reduced-motion:reduce){.flash.fire{animation:none}}
