<header><div class="identity"><span class="mark" aria-hidden="true">◉</span><span>OGDEN POINT / FRAME CLUB</span></div><a href="./">THE COLLECTION ↗</a></header>
<main><section class="intro"><div><div class="eyebrow">A small photo walk · Victoria, BC</div><h1>Same shore.<br><em>Different story.</em></h1></div><p>A lighthouse, a little boat, a lot of sea. Borrow the viewfinder and discover how much a photograph changes when you leave something out.</p></section>
<nav aria-label="Framing assignments" id="missions"></nav>
<div class="workbench"><section><div class="camera"><div class="camera-top"><span>FRAME CLUB · 35 MM</span><span id="shot-counter">FOUR FRAMES TO FIND</span></div><div class="viewfinder"><canvas id="scene" width="1200" height="800" tabindex="0" aria-label="Interactive seaside viewfinder. Drag to pan. Arrow keys move the frame, plus and minus zoom, Enter takes a picture."></canvas><div class="guide" id="guide"></div><div class="flash" id="flash"></div><div class="loading" id="loading">Developing the seaside…</div></div><div class="camera-bottom"><span id="camera-readout">VANCOUVER ISLAND · AFTERNOON</span><button id="grid" aria-pressed="true">Thirds grid: on</button></div></div><p class="note">Drag the scene to reframe, or use the sliders. Keyboard: arrows to pan, + / − to zoom, Enter to take a shot.</p></section>
<aside class="brief"><div class="assignment"><div class="readout" id="assignment-count"></div><h2 id="mission-title"></h2><p id="mission-description"></p></div><div class="dials"><label for="zoom">LENS / ZOOM <output id="zoom-value"></output></label><input id="zoom" type="range" min="1" max="3" step=".01" value="1"><label for="pan-x">LOOK LEFT / RIGHT</label><input id="pan-x" type="range" min="0" max="100" step=".1" value="50"><label for="pan-y">LOOK UP / DOWN</label><input id="pan-y" type="range" min="0" max="100" step=".1" value="50"></div><div class="actions"><button class="shutter" id="capture" disabled>TAKE THE SHOT</button><div class="secondary"><button id="hint" disabled>Try a starting frame</button><button id="reset">Reset view</button></div></div><div class="feedback" id="feedback" role="status" aria-live="polite">No rush. The lighthouse has nowhere to be.</div></aside></div>
<section aria-label="Your best shots"><div class="film-heading"><h2>Your contact sheet</h2><div><p id="progress">0 / 4 frames collected</p><button id="save-sheet" style="font:10px Courier New,monospace;margin-top:10px" disabled>Save contact sheet ↓</button></div></div><div class="film" id="film"></div></section>
<section class="closing"><div><div class="eyebrow">From the archive · July 19, 2004</div><h2>A lesson at the water's edge</h2><p>Jon left a tiny note about Ji-Hwan giving him photography tips at Ogden Point. That was enough for a little photo walk of our own. Inspired by Jon's <a href="?source=1">note about photography tips at Ogden Point</a>.</p></div><div><h2>Guidelines, not commandments</h2><p>The rule of thirds is a useful place to start, not a law of beauty. These four briefs score how closely you follow a particular composition request. A low score can still be a lovely photograph. The scene is an original AI-generated imagining of Ogden Point, not Jon's 2004 photo.</p></div></section></main>
<footer><span>A LITTLE EXPERIMENT BY CHLOE</span><span>Best shots stay in this browser when storage is available. No photos are uploaded.</span></footer>
<script>
'use strict';
const $=id=>document.getElementById(id);
const missions=[
 {title:'The lighthouse portrait',short:'Lighthouse',desc:'Give the lighthouse the upper-right crossing of the thirds grid. Leave a little world around it.',point:[.739,.398],target:[2/3,1/3],lesson:'An off-centre subject gives the eye somewhere to travel. Try this with a person on your next walk.'},
 {title:'A small boat, a big sea',short:'Little boat',desc:'Find the red sailboat. Place it at the lower-left crossing, with breathing room above and beside it.',point:[.278,.476],target:[1/3,2/3],lesson:'A small subject can tell a large story when you give its surroundings room.'},
 {title:'Let the sea speak',short:'Mostly sea',desc:'Put the distant sea horizon on the upper horizontal third. Make the water, rather than the sky, the main event.',horizon:true,target:1/3,lesson:'A high horizon makes the foreground feel expansive. The water gets to do the talking.'},
 {title:'Room for the sky',short:'Mostly sky',desc:'Now put that same distant horizon on the lower horizontal third. Notice how the mood changes.',horizon:true,target:2/3,lesson:'A low horizon gives the sky the lead. Same place, different emphasis.'}
];
const canvas=$('scene'),ctx=canvas.getContext('2d'),image=new Image();let ready=false,current=0,shots={},drag=null,grid=true;
const horizon=.4275;
try{const s=JSON.parse(localStorage.getItem('ogden-frame-club-v1')||'{}');for(let i=0;i<4;i++){let v=s[i];if(v&&typeof v.score==='number'&&typeof v.photo==='string'&&v.photo.startsWith('data:image/jpeg;base64,')&&v.photo.length<700000)shots[i]=v;}}catch(e){}
const values=()=>({z:Number($('zoom').value),x:Number($('pan-x').value)/100,y:Number($('pan-y').value)/100});
function rect(){const {z,x,y}=values();const w=image.width/z,h=image.height/z;return{x:(image.width-w)*x,y:(image.height-h)*y,w,h};}
function draw(){const {z}=values();$('zoom-value').textContent=z.toFixed(2)+'×';$('camera-readout').textContent='OGDEN POINT · '+z.toFixed(2)+'× · FRAME '+(current+1);if(!ready)return;const r=rect();ctx.drawImage(image,r.x,r.y,r.w,r.h,0,0,1200,800);}
function select(i){current=i;document.querySelectorAll('nav button').forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));$('assignment-count').textContent='ASSIGNMENT 0'+(i+1)+' / 04';$('mission-title').textContent=missions[i].title;$('mission-description').textContent=missions[i].desc;$('feedback').textContent='Move the frame, then take a shot. You can keep trying; only your best one stays.';draw();}
missions.forEach((m,i)=>{const b=document.createElement('button');b.innerHTML='<span>FRAME 0'+(i+1)+'</span>'+m.short;b.onclick=()=>select(i);$('missions').append(b);});
function renderFilm(){$('film').replaceChildren();$('save-sheet').disabled=Object.keys(shots).length===0;let n=Object.keys(shots).length;$('progress').textContent=n+' / 4 frames collected';$('shot-counter').textContent=n===4?'CONTACT SHEET COMPLETE':(4-n)+' FRAMES TO FIND';missions.forEach((m,i)=>{const card=document.createElement('article');card.className='print';const s=shots[i];if(s){const img=document.createElement('img');img.src=s.photo;img.alt='Your framing of '+m.short;card.append(img);}else{const blank=document.createElement('div');blank.className='blank';blank.textContent='0'+(i+1);card.append(blank);}const title=document.createElement('h3');title.textContent=m.short;card.append(title);const text=document.createElement('p');text.textContent=s?'BEST FRAME · '+s.score+'/100':'AWAITING A LITTLE LOOK';card.append(text);if(s){const b=document.createElement('button');b.textContent='Save photo ↓';b.onclick=()=>{const a=document.createElement('a');a.href=s.photo;a.download='ogden-point-frame-'+(i+1)+'.jpg';a.click();};card.append(b);}$('film').append(card);});}
$('save-sheet').onclick=async()=>{const sheet=document.createElement('canvas');sheet.width=1600;sheet.height=1280;const c=sheet.getContext('2d');c.fillStyle='#eee9db';c.fillRect(0,0,1600,1280);c.fillStyle='#203e3a';c.font='48px Georgia';c.fillText('Ogden Point Frame Club',70,85);c.font='21px monospace';c.fillText('SAME SHORE. DIFFERENT STORY.',70,125);for(let i=0;i<4;i++){const x=70+(i%2)*770,y=170+Math.floor(i/2)*530;c.fillStyle='#faf8f0';c.fillRect(x,y,720,500);if(shots[i]){const im=new Image();im.src=shots[i].photo;await im.decode();c.drawImage(im,x+18,y+18,684,456);}else{c.fillStyle='#d7dacd';c.fillRect(x+18,y+18,684,456);}c.fillStyle='#203e3a';c.font='18px Georgia';c.fillText(missions[i].short+(shots[i]?' · '+shots[i].score+'/100':''),x+22,y+493);}c.font='16px Georgia';c.fillText('An original AI-generated imagining of Ogden Point. Framed by you.',70,1250);const a=document.createElement('a');a.download='ogden-point-contact-sheet.jpg';a.href=sheet.toDataURL('image/jpeg',.9);a.click();};
function score(){const m=missions[current],r=rect();let error;if(m.horizon){const p=(horizon*image.height-r.y)/r.h;error=Math.abs(p-m.target);}else{const x=(m.point[0]*image.width-r.x)/r.w,y=(m.point[1]*image.height-r.y)/r.h;if(x<0||x>1||y<0||y>1)return 0;error=Math.hypot(x-m.target[0],y-m.target[1]);}return Math.max(0,Math.round(100-error*220));}
function capture(){if(!ready)return;const s=score(),photo=canvas.toDataURL('image/jpeg',.82);const better=!shots[current]||s>shots[current].score;if(better){shots[current]={score:s,photo};try{localStorage.setItem('ogden-frame-club-v1',JSON.stringify(shots));}catch(e){}renderFilm();}$('feedback').replaceChildren();const strong=document.createElement('strong');strong.textContent=s+'/100 · '+(s>=90?'Beautifully framed.':s>=70?'Getting close.':'Another way to see it.');$('feedback').append(strong,document.createTextNode((better?'New best shot. ':'Your best shot stays on the sheet. ')+(s>=90?missions[current].lesson:missions[current].horizon?'Try aligning the distant sea horizon with the requested horizontal line.':'Try moving the subject toward the requested grid crossing. The zoom dial gives you more room to move.')));$('flash').classList.remove('fire');void $('flash').offsetWidth;$('flash').classList.add('fire');}
function hint(){if(!ready)return;const m=missions[current],z=2.1;let x=.5,y=.5;if(m.horizon){y=(horizon-m.target/z)/(1-1/z);}else{x=(m.point[0]-m.target[0]/z)/(1-1/z);y=(m.point[1]-m.target[1]/z)/(1-1/z);}$('zoom').value=z;$('pan-x').value=Math.max(0,Math.min(100,x*100));$('pan-y').value=Math.max(0,Math.min(100,y*100));draw();$('feedback').textContent='Here is one possible starting frame. Look at the grid crossing, then try nudging it your own way.';}
['zoom','pan-x','pan-y'].forEach(id=>$(id).oninput=draw);$('capture').onclick=capture;$('hint').onclick=hint;
$('reset').onclick=()=>{$('zoom').value=1;$('pan-x').value=50;$('pan-y').value=50;draw();$('feedback').textContent='Back to the whole scene. Your saved shots are still below.';};
$('grid').onclick=()=>{grid=!grid;$('guide').classList.toggle('off',!grid);$('grid').setAttribute('aria-pressed',grid);$('grid').textContent='Thirds grid: '+(grid?'on':'off');};
canvas.addEventListener('pointerdown',e=>{if(!ready)return;canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,px:Number($('pan-x').value),py:Number($('pan-y').value)};});
canvas.addEventListener('pointermove',e=>{if(!drag)return;const {z}=values();if(z<=1)return;const bounds=canvas.getBoundingClientRect();$('pan-x').value=Math.max(0,Math.min(100,drag.px-(e.clientX-drag.x)/bounds.width*100/(z-1)));$('pan-y').value=Math.max(0,Math.min(100,drag.py-(e.clientY-drag.y)/bounds.height*100/(z-1)));draw();});
['pointerup','pointercancel','lostpointercapture'].forEach(ev=>canvas.addEventListener(ev,()=>drag=null));
canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','Enter',' '].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')$('pan-x').value-=3;if(e.key==='ArrowRight')$('pan-x').value=Number($('pan-x').value)+3;if(e.key==='ArrowUp')$('pan-y').value-=3;if(e.key==='ArrowDown')$('pan-y').value=Number($('pan-y').value)+3;if(e.key==='+'||e.key==='=')$('zoom').value=Number($('zoom').value)+.1;if(e.key==='-')$('zoom').value-=.1;if(e.key==='Enter'||e.key===' ')capture();draw();};
image.onload=()=>{ready=true;$('loading').hidden=true;$('capture').disabled=false;$('hint').disabled=false;draw();};
image.onerror=()=>{$('loading').textContent='The seaside could not load. Please refresh to try again.';};
image.src='?art=1';select(0);renderFilm();draw();
</script></body></html>